test("deleted records do not end a paged export early (CAT-284)", () => {
  const gateway = new MemoryGateway({ invoices: [{id:"i-1",name:"A"},{id:"i-2",name:"B",deleted:true},{id:"i-3",name:"C"}] });
  const result = exportCatalog(gateway, "invoices", {pageSize:2});
  assert.deepEqual(result.entries.map(r=>r.id), ["i-1","i-3"]);
  assert.equal(result.count, 2);
});
test("pages past runs of deleted records", () => {
  const rows = [{id:"1",name:"a"},{id:"2",name:"b",deleted:true},{id:"3",name:"c",deleted:true},{id:"4",name:"d",deleted:true},{id:"5",name:"e"},{id:"6",name:"f"},{id:"7",name:"g",deleted:true}];
  const gateway = new MemoryGateway({ invoices: rows });
  assert.deepEqual(exportCatalog(gateway, "invoices", {pageSize:2}).entries.map(r=>r.id), ["1","5","6"]);
});
EOF
